package com.flowcraft.api.workflow;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="workflows") public class WorkflowEntity { @Id private UUID id; @Column(name="owner_id",nullable=false) private UUID ownerId; @Column(nullable=false) private String name; @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private String graph; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected WorkflowEntity(){} public WorkflowEntity(UUID id,UUID ownerId,String name,String graph){this.id=id;this.ownerId=ownerId;this.name=name;this.graph=graph;createdAt=updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getOwnerId(){return ownerId;} public String getGraph(){return graph;} public void update(String name,String graph){this.name=name;this.graph=graph;updatedAt=Instant.now();} }
